"""Random ranges and query values, weighted towards the shape a chained
low <= value <= high comparison gets wrong: values just past one edge."""


def generate(rng, count):
    builders = (_inside, _just_outside, _wide_range, _single_point)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, rows, description=""):
    lines = ["%d %d %d" % row for row in rows]
    return {
        "name": name,
        "stdin": "\n".join(lines) + "\n",
        "description": description,
    }


def _bounds(rng):
    a = rng.randint(-100000, 100000)
    b = rng.randint(-100000, 100000)
    return (a, b) if a <= b else (b, a)


def _inside(rng, index):
    rows = []
    for _ in range(4):
        low, high = _bounds(rng)
        value = rng.randint(low, high)
        rows.append((value, low, high))
    return _case("values chosen inside their range #%d" % index, rows)


def _just_outside(rng, index):
    rows = []
    for _ in range(4):
        low, high = _bounds(rng)
        if rng.random() < 0.5:
            value = low - rng.randint(1, 5)
        else:
            value = high + rng.randint(1, 5)
        rows.append((value, low, high))
    return _case("values just past one edge of the range #%d" % index, rows,
                 "Exactly the shape a chained low <= value <= high gets "
                 "wrong.")


def _wide_range(rng, index):
    rows = []
    for _ in range(3):
        low = rng.randint(-2000000000, 0)
        high = rng.randint(0, 2000000000)
        value = rng.randint(-2000000000, 2000000000)
        rows.append((value, low, high))
    return _case("a wide range spanning most of int32 #%d" % index, rows)


def _single_point(rng, index):
    rows = []
    for _ in range(3):
        point = rng.randint(-1000, 1000)
        value = point + rng.choice((-1, 0, 1))
        rows.append((value, point, point))
    return _case("a single-point range, low == high #%d" % index, rows)
